//! Hidden treasure chest locations.
//!
//! Hercules ships 146 cloaked treasure chests
//! (`npc/re/other/achievement_treasures.txt`). Each uncloaks for a player
//! standing near it who has not opened it yet. The locations are static, so the
//! Adventure Guide can list them per map. Whether a given character has already
//! opened one is server state the client is not sent, so this table
//! deliberately says nothing about what has been found.
//!
//! Generated by `Hercules/tools/gen-chests.py`; `tools/check-campaign.sh` fails
//! if this file has drifted from the scripts. Do not edit by hand.

use std::sync::OnceLock;

use hashbrown::HashMap;

const CHESTS: &str = include_str!("chests.tsv");

/// One chest's cell.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HiddenChest {
    pub id: u32,
    pub x: u16,
    pub y: u16,
}

/// Chests for a map, in the manifest's order. Empty for a map with none.
pub fn hidden_chests_for_map(map_name: &str) -> &'static [HiddenChest] {
    static TABLE: OnceLock<HashMap<String, Vec<HiddenChest>>> = OnceLock::new();

    TABLE
        .get_or_init(|| parse_chests(CHESTS))
        .get(&map_name.to_ascii_lowercase())
        .map_or(&[], Vec::as_slice)
}

fn parse_chests(data: &str) -> HashMap<String, Vec<HiddenChest>> {
    let mut by_map: HashMap<String, Vec<HiddenChest>> = HashMap::new();

    for line in data.lines() {
        let line = line.trim_end();
        // The header row starts with "id", comments with '#'.
        if line.is_empty() || line.starts_with('#') || line.starts_with("id\t") {
            continue;
        }

        // id, map, x, y, region, title, hat_id
        let mut fields = line.split('\t');
        let (Some(id), Some(map_name), Some(x), Some(y)) = (fields.next(), fields.next(), fields.next(), fields.next()) else {
            continue;
        };
        let (Ok(id), Ok(x), Ok(y)) = (id.trim().parse::<u32>(), x.trim().parse::<u16>(), y.trim().parse::<u16>()) else {
            continue;
        };
        let map_name = map_name.trim().to_ascii_lowercase();
        if map_name.is_empty() {
            continue;
        }

        by_map.entry(map_name).or_default().push(HiddenChest { id, x, y });
    }

    by_map
}

#[cfg(test)]
mod tests {
    use super::{CHESTS, HiddenChest, hidden_chests_for_map, parse_chests};

    /// The manifest has to parse to every chest Hercules ships, or the Guide
    /// quietly lists fewer than exist.
    #[test]
    fn the_bundled_manifest_holds_every_chest() {
        let table = parse_chests(CHESTS);
        let total: usize = table.values().map(Vec::len).sum();
        assert_eq!(total, 146);
    }

    #[test]
    fn a_known_chest_is_found_by_map_regardless_of_case() {
        assert_eq!(hidden_chests_for_map("prt_fild01"), [HiddenChest {
            id: 120001,
            x: 146,
            y: 126
        }]);
        assert_eq!(hidden_chests_for_map("PRT_FILD01").len(), 1);
    }

    #[test]
    fn a_map_with_no_chest_has_an_empty_list() {
        assert!(hidden_chests_for_map("prontera").is_empty());
    }

    #[test]
    fn no_two_chests_share_an_id_or_a_cell() {
        let table = parse_chests(CHESTS);
        let mut ids = hashbrown::HashSet::new();
        let mut cells = hashbrown::HashSet::new();
        for (map, chests) in &table {
            for chest in chests {
                assert!(ids.insert(chest.id), "duplicate chest id {}", chest.id);
                assert!(
                    cells.insert((map.clone(), chest.x, chest.y)),
                    "duplicate cell {map} {},{}",
                    chest.x,
                    chest.y
                );
            }
        }
    }

    #[test]
    fn header_comments_and_malformed_rows_are_skipped() {
        let table = parse_chests("# schema_version: 1\nid\tmap\tx\ty\n120001\tprt_fild01\t1\t2\nbad\tprt_fild01\t1\t2\n120002\t\t1\t2\n");
        assert_eq!(table.len(), 1);
        assert_eq!(table["prt_fild01"].len(), 1);
    }
}
